<script setup lang="ts">
definePageMeta({ layout: 'dashboard', middleware: 'admin' }); useSeoMeta({ title: 'Événements', robots: 'noindex' })
const toast = useToast(); const { data, refresh } = await useAsyncData('adm-events', () => api<any[]>('/api/admin/events'), { server: false })
async function mod(e: any, moderation: string) { try { await api(`/api/admin/events/${e.id}/moderate`, { method: 'POST', body: { moderation } }); toast.ok('Modération appliquée'); refresh() } catch (er) { toast.err(errMsg(er)) } }
</script>
<template><div class="space-y-6"><h1 class="text-[clamp(1.8rem,4vw,2.6rem)] font-black">Événements et modération</h1><div class="card overflow-x-auto"><table class="w-full min-w-[720px]"><thead><tr><th class="th">Événement</th><th class="th">Organisation</th><th class="th">Statut</th><th class="th">Modération</th><th class="th">Signalements</th><th class="th" /></tr></thead><tbody class="divide-y divide-line"><tr v-for="e in data" :key="e.id"><td class="td"><NuxtLink :to="`/events/${e.slug}`" class="font-semibold hover:text-accent" target="_blank">{{ e.title }}</NuxtLink><span v-if="e.isDemo" class="chip ml-2 text-amber-300">démo</span></td><td class="td text-muted">{{ e.org }}</td><td class="td capitalize">{{ e.status }}</td><td class="td capitalize" :class="e.moderation === 'ok' ? '' : 'text-red-300'">{{ e.moderation }}</td><td class="td">{{ e.reports }}</td><td class="td text-right"><button v-if="e.moderation === 'ok'" class="btn btn-danger !min-h-[36px] px-3" @click="mod(e, 'flagged')">Suspendre (modération)</button><button v-else class="btn btn-ghost !min-h-[36px] px-3" @click="mod(e, 'ok')">Lever</button></td></tr></tbody></table></div></div></template>
